update hr_employee_no_sequence
set current_value = #{nextValue},
    update_time = sysdate()
where sequence_key = #{sequenceKey}
  and current_value = #{expectedValue}

update sys_user_profile
job_grade = #{values.jobGrade}, direct_supervisor_user_id = #{values.directSupervisorUserId}, employee_status = #{values.employeeStatus}, employee_category = #{values.employeeCategory}, birth_date = #{values.birthDate}, id_type = #{values.idType}, id_number = #{values.idNumber}, blood_type = #{values.bloodType}, registered_residence = #{values.registeredResidence}, current_address = #{values.currentAddress}, first_education = #{values.firstEducation}, first_degree = #{values.firstDegree}, first_graduation_date = #{values.firstGraduationDate}, first_graduation_school = #{values.firstGraduationSchool}, first_major = #{values.firstMajor}, highest_education = #{values.highestEducation}, highest_degree = #{values.highestDegree}, highest_graduation_date = #{values.highestGraduationDate}, highest_graduation_school = #{values.highestGraduationSchool}, highest_major = #{values.highestMajor}, political_status = #{values.politicalStatus}, marital_status = #{values.maritalStatus}, nationality = #{values.nationality}, foreign_national_flag = #{values.foreignNationalFlag}, ethnicity = #{values.ethnicity}, health_status = #{values.healthStatus}, emergency_contact = #{values.emergencyContact}, emergency_contact_relation = #{values.emergencyContactRelation}, emergency_contact_phone = #{values.emergencyContactPhone}, recruitment_channel = #{values.recruitmentChannel}, office_phone = #{values.officePhone}, work_start_date = #{values.workStartDate}, entry_date = #{values.entryDate}, probation_period = #{values.probationPeriod}, planned_regularization_date = #{values.plannedRegularizationDate}, actual_regularization_date = #{values.actualRegularizationDate}, current_position_start_date = #{values.currentPositionStartDate}, contract_start_date = #{values.contractStartDate}, contract_end_date = #{values.contractEndDate}, contract_type = #{values.contractType}, renewal_count = #{values.renewalCount}, work_location = #{values.workLocation}, work_city_level = #{values.workCityLevel}, attendance_method = #{values.attendanceMethod}, household_type = #{values.householdType}, social_type = #{values.socialType}, social_security_location = #{values.socialSecurityLocation}, housing_fund_location = #{values.housingFundLocation}, leave_date = #{values.leaveDate}, bank_name = #{values.bankName}, bank_account = #{values.bankAccount}, legal_entity = #{values.legalEntity}, update_by = #{operator}, update_time = sysdate()
where user_id = #{userId}

mapper.select:
select p.user_id
from sys_user_profile p
     inner join sys_user u on u.user_id = p.user_id
where p.contract_end_date >= #{windowStart}
  and p.contract_end_date <= #{windowEnd}
  and p.employee_status <> '离职'
  and p.user_id > #{afterUserId}
  and u.del_flag = '0'
order by p.user_id asc
limit #{limit}

mapper.update:
update sys_user_profile
set employee_status = '离职',
    leave_date = #{snapshot.leaveDate},
    update_by = #{operatorName},
    update_time = sysdate()
where user_id = #{snapshot.employeeId}
  and employee_status = #{expectedEmployeeStatus}
  and leave_date <=> #{expectedLeaveDate}
